// Extract incoming fields from multipart/form-data or JSON body
const body = $json.body || $json;
const patientId = body.patientId || 'P1001';
const patientName = body.patientName || 'Patient';
const language = body.language || 'English';
const dischargeDate = body.dischargeDate || new Date().toISOString().split('T')[0];
const fileText = body.fileContent || body.clinicalNotes || 'Discharge Clinical Summary: Patient is recovering following hospital treatment. Follow prescribed medications and rest.';

return [{
  json: {
    patientId,
    patientName,
    language,
    dischargeDate,
    clinicalNotes: fileText
  }
}];

