// Parse LLM Output and format response for MedGuideAI
const inputData = $('Parse Patient & Document Info').first().json;
const response = $json;
let parsedResult = {};

try {
  const rawText = response.candidates?.[0]?.content?.parts?.[0]?.text || response.text || '{}';
  const cleanJson = rawText.replace(/```json\n?|```/g, '').trim();
  parsedResult = JSON.parse(cleanJson);
} catch (e) {
  parsedResult = {
    diagnosis: ['Clinical Procedure Recovery'],
    medications: [
      {
        name: 'Prescribed Regimen',
        dosage: 'As directed',
        frequency: 'Daily',
        duration: '7-14 days',
        explanation: 'Take as directed on medicine package.'
      }
    ],
    diet: ['Balanced diet with plenty of fluids'],
    restrictions: ['Rest and avoid heavy exertion'],
    followUp: ['Follow up with your primary physician in 1-2 weeks'],
    warningSigns: ['High fever', 'Severe pain', 'Shortness of breath'],
    patientExplanation: 'Please rest and follow the prescribed medications carefully. Contact the hospital if you experience severe symptoms.'
  };
}

const formattedPatient = {
  id: inputData.patientId,
  name: inputData.patientName,
  language: inputData.language,
  dischargeDate: inputData.dischargeDate,
  processingStatus: 'Completed',
  whatsappStatus: 'Pending',
  diagnosis: parsedResult.diagnosis || [],
  medications: parsedResult.medications || [],
  diet: parsedResult.diet || [],
  restrictions: parsedResult.restrictions || [],
  followUp: parsedResult.followUp || [],
  warningSigns: parsedResult.warningSigns || [],
  patientExplanation: parsedResult.patientExplanation || ''
};

return [{
  json: {
    status: 'success',
    patient: formattedPatient,
    summary: formattedPatient,
    patient_explanation: formattedPatient.patientExplanation,
    communication: {
      whatsapp_status: 'pending'
    }
  }
}];
